// Chunk 51, gap-g8#1: Create Seedelf refuses a tag outside printable ASCII, which the deployed policy takes.
//
// The deployed policy (5b82530: validators/seedelf.ak, lib/token_name.ak) reads its redeemer as any ByteArray and
// names the token prefix ‖ the tag's first 15 bytes ‖ the first input's index ‖ its tx id, cut to 32 bytes. The
// kernel-checked Seedelf.Every.policy_accepts_iff (seedelf-verification/Seedelf/Every/PolicyTyped.lean) says the
// deployed bytes accept exactly that: a `.B tag` redeemer, named by seedelfName, with no rule on the tag's bytes.
// Core writes a tag's UTF-8 bytes, cut at 15, into both the name and the redeemer (seedelf_token_name,
// create_mint_redeemer), and the CLI's create takes any text. The web wallet refuses any character outside " ".."~",
// in the form (shared/label.ts labelProblem) and in WebAssembly (check_label, which buildMint runs first), so "José"
// or "さくら" can't be a tag here.
//
// The right behaviour: the form lets Review on for such a tag, and the worker builds the mint, named and redeemed as
// the policy names it. A stealth mint is measured in the wallet with the deployed scripts (core's measure_locally),
// so once the rule is gone this build is itself a run of the deployed policy on that tag. An ASCII tag builds today,
// as the control: the harness and the name are right, and only the character differs.
import { describe, expect, it } from "vitest";

import { SESSION_MINT } from "../src/background/mint";
import { labelProblem, tokenNamePrefix } from "../src/shared/label";
import { testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const utf8 = (s: string) => Buffer.from(s, "utf8").toString("hex");

/** The name the deployed policy gives a Seedelf minted with `tag`, its first input `txid#idx` (seedelfName). */
function policyName(txid: string, idx: number, tag: string): string {
  return `5eed0e1f${utf8(tag).slice(0, 30)}${idx.toString(16).padStart(2, "0")}${txid}`.slice(0, 64);
}

async function unlocked() {
  const v = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
  const t = testBalances();
  await t.wallet.create(v.phrase, PASSWORD);
  return t;
}

describe("gap-g8#1: a tag the deployed policy takes", () => {
  it("the form lets Review on for a tag outside printable ASCII", () => {
    expect.soft(labelProblem("José"), "José, 5 bytes of UTF-8").toBeUndefined();
    expect.soft(labelProblem("さくら"), "さくら, 9 bytes of UTF-8").toBeUndefined();
  });

  it("the worker builds it, named and redeemed as the policy names it", async () => {
    const t = await unlocked();
    // The control: named after the 25 ₳ UTxO that pays (a1… #0), as mint.test.ts has it.
    const control = await t.mint.build("preprod", "Jose", "seedelf");
    expect(control.tokenName).toBe(policyName("a1".repeat(32), 0, "Jose"));

    const summary = await t.mint.build("preprod", "José", "seedelf");
    expect(summary.tokenName).toBe(policyName("a1".repeat(32), 0, "José"));
    // The mint redeemer holds the tag's bytes: CBOR bytes of length 5.
    const built = (await t.session.get<{ txCbor: string }>(SESSION_MINT))!;
    expect(built.txCbor).toContain(`45${utf8("José")}`);
    // The form's preview is how that name starts.
    expect(summary.tokenName.startsWith(tokenNamePrefix("José"))).toBe(true);
  });
});

// Chunk 51, finding gap-g8#2 (its trace verifier's test). The public Send refuses the user's own Seedelf, alone or
// beside another recipient: send.ts:179 throws OWN_SEEDELF_FROM_ACCOUNT before anything is built, and the To field
// says the same (Destination.tsx:72). Yet WebAssembly's buildAccountSend and core's account_send_many build exactly
// that payment, as a move-in is built: an output at the wallet contract under a fresh re-randomization of a register
// the user's own Seedelf key spends. Paying a script address runs no script, so the ledger takes it.
//
// Step 1 shows the builder takes it, through Send's own `pay` (what `build` runs once each destination is read), and
// what the way round costs: a Send to the friend and a Make private, two fees. Step 2 asks Send itself, which refuses
// today, so this fails on TREE and passes once the refusal is lifted.
import { describe, expect, it } from "vitest";

import { registerOf, seedelfLabel } from "../src/background/chain";
import { readContractView } from "../src/background/contract-scan";
import { destinationResolver } from "../src/background/destination";
import { SESSION_SEND } from "../src/background/send";
import { holdsOwn } from "../src/background/transfer";
import type { PaymentAsk, SendSummary } from "../src/shared/rpc";
import { ownedUtxos, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
/** The 15-word phrase's receive address: a friend's. */
const FRIEND = account(15).preprod.receive_0 as string;
/** The 12-word phrase's own Seedelf, "web-wallet" (owned-utxos.json). */
const MINE = ownedUtxos[2]!.asset_list![0]!.asset_name;

interface DecodedOutput {
  address: { bech32: string; seedelf: boolean };
  lovelace: string;
  register?: { generator: string; publicValue: string; payable: boolean };
}

const ada = (lovelace: string | bigint) => (Number(lovelace) / 1e6).toFixed(6);

describe("the public Send and the user's own Seedelf (chunk 51, gap-g8#2)", () => {
  it("pays the user's own Seedelf from the public account, beside a friend or alone, as the builder already does", async () => {
    const t = testBalances();
    await t.wallet.create(account(12).phrase, PASSWORD);
    const { wasm } = t.deps;
    const deps = t.send["deps"];
    const toFriend: PaymentAsk = { to: FRIEND, lovelace: "10000000", tokens: [] };
    const toMine: PaymentAsk = { to: MINE, lovelace: "50000000", tokens: [] };

    // Send's own lookup: the contract view it reads, where this Seedelf is the wallet's own.
    const view = await readContractView(deps, "preprod");
    const recipient = view.seedelfs[MINE]!;
    expect(holdsOwn(view, recipient)).toBe(true);
    const held = registerOf(recipient)!;

    // What a built transaction pays: the friend, and each output at the wallet contract, with whether the user's own
    // Seedelf key spends its register and whether that register is a fresh one (not the Seedelf UTxO's own copied).
    const paid = async (txCbor: string) => {
      const tx = JSON.parse(wasm.decodeTx(wasm.Network.Preprod, txCbor)) as { outputs: DecodedOutput[] };
      const friend = tx.outputs.filter((o) => o.address.bech32 === FRIEND).map((o) => o.lovelace);
      const into = tx.outputs.filter((o) => o.address.seedelf);
      const contract = await t.wallet.withKeys((keys) =>
        into.map((o) => {
          const r = new wasm.Register(o.register!.generator, o.register!.publicValue);
          try {
            return {
              lovelace: o.lovelace,
              payable: o.register!.payable,
              ours: keys.seedelf.isOwned(r),
              fresh: o.register!.generator !== held.generator && o.register!.publicValue !== held.publicValue,
            };
          } finally {
            r.free();
          }
        }),
      );
      return { friend, contract };
    };
    const intoMine = [{ lovelace: "50000000", payable: true, ours: true, fresh: true }];

    // 1. The builder takes it: Send's `pay` with the destinations `build` reads, the own Seedelf as `seedelf()` makes
    //    it but for the refusal on send.ts:179.
    const friend = await destinationResolver(deps, "preprod")(FRIEND);
    const own = { address: recipient.address, own: false, seedelf: { name: MINE, label: seedelfLabel(MINE) }, recipient };
    const built = (await t.send["pay"]("preprod", [friend, own], [toFriend, toMine], SESSION_SEND)) as SendSummary;
    const builtTx = (await t.session.get<{ txCbor: string; txHash: string }>(SESSION_SEND))!;
    expect(builtTx.txHash).toBe(built.txHash);
    expect(await paid(builtTx.txCbor)).toEqual({ friend: ["10000000"], contract: intoMine });

    // The way round Send's words point to: the friend alone, then Make private. Two fees for one.
    const friendOnly = await t.send.build("preprod", [toFriend]);
    const madePrivate = await t.moveIn.build("preprod", "50000000", []);
    const extra = BigInt(friendOnly.fee) + BigInt(madePrivate.fee) - BigInt(built.fee);
    console.log(
      `[r51 gap-g8#2] one payment's fee ${ada(built.fee)} ₳; the way round: Send ${ada(friendOnly.fee)} ₳ + Make private ` +
        `${ada(madePrivate.fee)} ₳, ${ada(extra)} ₳ more`,
    );
    expect(extra).toBeGreaterThan(0n);

    // 2. Send itself, which refuses both before anything is built: the user's own Seedelf alone, and beside the friend.
    const outcome = (p: Promise<SendSummary>) =>
      p.then(
        (s) => s.payments.map((x) => ({ to: x.seedelf?.name ?? x.address, lovelace: x.lovelace })),
        (e: Error) => `refused: ${e.message}`,
      );
    const alone = await outcome(t.send.build("preprod", [toMine]));
    console.log(`[r51 gap-g8#2] Send to the user's own Seedelf alone: ${JSON.stringify(alone)}`);
    expect.soft(alone, "the user's own Seedelf alone").toEqual([{ to: MINE, lovelace: "50000000" }]);
    const both = await outcome(t.send.build("preprod", [toFriend, toMine]));
    console.log(`[r51 gap-g8#2] Send to a friend and the user's own Seedelf: ${JSON.stringify(both)}`);
    expect(both, "a friend and the user's own Seedelf, in one payment").toEqual([
      { to: FRIEND, lovelace: "10000000" },
      { to: MINE, lovelace: "50000000" },
    ]);
    // Once it builds, it pays as the builder does: the friend, and the user's own Seedelf under a fresh register of theirs.
    const kept = (await t.session.get<{ txCbor: string }>(SESSION_SEND))!;
    expect(await paid(kept.txCbor)).toEqual({ friend: ["10000000"], contract: intoMine });
  });
});

//! Chunk 51, gap-g8#3: a note longer than 64 characters. The ledger holds
//! each metadata text to 64 bytes and nothing more (cardano-ledger's
//! `validMetadatum`: `S s` at most 64 bytes, a `List` of any length), so
//! CIP-20's `msg` takes as many 64-byte lines as the transaction's 16 KiB
//! holds. Core already cuts a note into such lines (`note.rs` `split`), and
//! `settle` prices every draft with the note patched in. So a 120-character
//! payment reference should go on a send whole, as two lines that fit, with
//! a fee that pays for them. Today `Note::new` refuses it.

use pallas_addresses::Address;
use pallas_crypto::hash::Hasher;
use pallas_primitives::{Metadatum, Nullable};
use pallas_traverse::MultiEraTx;
use seedelf_core::build::{
    self, AccountAmount, AccountPay, MAX_TX_SIZE, Payee, fake_signer, tx_id,
};
use seedelf_core::note::{NOTE_LABEL, Note};
use seedelf_core::staking::Staking;
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

/// A payment reference a user might paste: 120 characters, all ASCII.
const REFERENCE: &str = "Invoice 2026-118 for October: 14 hours of design work at 85 EUR, purchase order PO-77341, client ref ACME/NL/042. Thanks";

fn params() -> ProtocolParameters {
    let rows: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    ProtocolParameters::from_koios(&rows[0]).unwrap()
}

fn utxo(account: &CardanoAccount, lovelace: u64) -> UtxoResponse {
    UtxoResponse {
        tx_hash: hex::encode([7u8; 32]),
        tx_index: 0,
        address: account
            .base_address(true, Role::Receive, 0)
            .unwrap()
            .to_bech32()
            .unwrap(),
        value: lovelace.to_string(),
        payment_cred: hex::encode(account.key_hash(Role::Receive, 0).unwrap()),
        asset_list: Some(vec![]),
        ..Default::default()
    }
}

/// CIP-20's lines under label 674, and whether the body's hash of the
/// auxiliary data matches its bytes.
fn message_of(bytes: &[u8]) -> (Vec<String>, bool) {
    let tx = MultiEraTx::decode(bytes).unwrap();
    let conway = tx.as_conway().unwrap();
    let Nullable::Some(raw) = &conway.auxiliary_data else {
        panic!("no auxiliary data");
    };
    let hash = conway
        .transaction_body
        .auxiliary_data_hash
        .as_ref()
        .unwrap();
    let matches = hash.to_vec() == Hasher::<256>::hash(raw.raw_cbor()).to_vec();
    let Some(Metadatum::Map(message)) = tx.metadata().find(NOTE_LABEL).cloned() else {
        panic!("no message under 674");
    };
    let lines = message
        .iter()
        .find(|(k, _)| *k == Metadatum::Text("msg".to_string()))
        .map(|(_, v)| match v {
            Metadatum::Array(lines) => lines
                .iter()
                .map(|l| match l {
                    Metadatum::Text(t) => t.clone(),
                    other => panic!("a line that isn't text: {other:?}"),
                })
                .collect(),
            other => panic!("msg isn't a list: {other:?}"),
        })
        .unwrap();
    (lines, matches)
}

#[test]
fn a_120_character_note_goes_on_a_send_whole_in_lines_the_ledger_takes() {
    assert_eq!((REFERENCE.chars().count(), REFERENCE.len()), (120, 120));

    // The ledger takes it: two of CIP-20's lines, each at most 64 bytes.
    let note = Note::new(REFERENCE)
        .expect("a 120-character note fits CIP-20's msg as two 64-byte lines")
        .expect("not empty");
    assert_eq!(note.text(), REFERENCE, "the review shows the whole reference");
    assert!(note.lines().len() >= 2, "{:?}", note.lines());
    assert!(
        note.lines().iter().all(|l| !l.is_empty() && l.len() <= 64),
        "each line within the ledger's 64 bytes: {:?}",
        note.lines()
    );
    assert_eq!(
        note.lines().join(" "),
        REFERENCE,
        "cut only at spaces, so a reader rejoins it whole"
    );

    // On a send: the lines under 674's msg, the body's hash of them, the
    // transaction's hash, a fee that pays for them, and under 16 KiB.
    let account = CardanoAccount::from_phrase(PHRASE, 0).unwrap();
    let to: Address = CardanoAccount::from_phrase(PHRASE, 1)
        .unwrap()
        .base_address(true, Role::Receive, 0)
        .unwrap();
    let params = params();
    let built = build::account_send_many(
        &params,
        &[utxo(&account, 20_000_000)],
        &[AccountPay::new(
            Payee::Address(&to),
            AccountAmount::Lovelace(5_000_000),
            &[],
        )],
        true,
        &account.base_address(true, Role::Receive, 0).unwrap(),
        &Staking::none(),
        Some(&note),
        None,
    )
    .expect("a send carrying the 120-character note builds");

    let (lines, hash_matches) = message_of(&built.tx.tx_bytes.0);
    assert_eq!(lines, note.lines(), "the transaction carries every line");
    assert!(
        hash_matches,
        "the body carries the hash of the note's bytes"
    );
    assert_eq!(built.tx.tx_hash.0, *tx_id(&built.tx.tx_bytes.0).unwrap());

    let signed = built.tx.clone().sign(fake_signer()).unwrap();
    let size = signed.tx_bytes.0.len() as u64;
    assert!(size <= MAX_TX_SIZE, "{size} bytes");
    let minimum = params.min_fee_a * size + params.min_fee_b;
    assert!(built.fee >= minimum, "fee {} < {minimum}", built.fee);
    assert!(built.fee < minimum + 1_000);
    assert_eq!(built.change_lovelace, 20_000_000 - 5_000_000 - built.fee);
    eprintln!(
        "120-character note: lines {:?}, signed size {size} bytes, fee {} lovelace",
        note.lines(),
        built.fee
    );
}

//! Chunk 51, finding gap-g8#4: a payment pays at most 20 recipients, on
//! either side. WebAssembly's `MAX_RECIPIENTS` (20) is checked by
//! `check_recipients` in `account_send`, `transfer_plan` and `withdrawal_of`,
//! and the extension's `shared/recipients.ts` holds the same 20. Core has no
//! count rule: its `settle` refuses only a transaction over the ledger's
//! 16 KiB (`build::MAX_TX_SIZE`), and the deployed wallet validator never reads
//! a transaction's outputs, so more recipients add nothing to its scripts' cost.
//!
//! Each test asks for 25 recipients, each a different address or Seedelf, at
//! 2 ADA each, through the function the worker's binding calls
//! (`buildAccountSend`, `buildTransferParts`, `buildWithdrawParts`). Each
//! asserts the right behaviour: one transaction that pays every recipient
//! exactly what was asked and fits the ledger's size limit. They fail while
//! the cap is there.

use pallas_primitives::alonzo::{Constr, MaybeIndefArray, PlutusData};
use pallas_primitives::conway::DatumOption;
use pallas_traverse::MultiEraTx;
use seedelf_core::build::MAX_TX_SIZE;
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_crypto::derivation::seedelf_key_v1;
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{InlineDatum, UtxoResponse};
use seedelf_wasm::api::{
    self, PathedUtxo, SeedelfPayment, SendPayment, SendRequest, TransferRequest, WithdrawPayment,
    WithdrawRequest,
};
use serde_json::{Value, json};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

/// More recipients than `api::MAX_RECIPIENTS` (20).
const RECIPIENTS: usize = 25;
/// What each recipient is paid.
const EACH: u64 = 2_000_000;
/// A private spend's `tx_cbor` is unsigned: giveme.my's and the one-time key's
/// witnesses add 2 × 101 bytes, and the witness set's key and array header.
const TWO_WITNESSES: u64 = 2 * 101 + 5;

fn fixture(path: &str) -> Value {
    let path = format!("{}/{path}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn params() -> Value {
    fixture("../../seedelf-core/tests/fixtures/epoch_params.json")[0].clone()
}

/// The 12-word phrase's real preprod UTxOs, each with its derivation path (as
/// api_test.rs's `account_utxos`): 10,350.54 ADA in 6 UTxOs.
fn account_utxos(account: &CardanoAccount) -> Vec<PathedUtxo> {
    let doc = fixture("../extension/tests/fixtures/koios-preprod.json");
    let stake = account.stake_address(true).unwrap().to_bech32().unwrap();
    let rows = doc["accounts"][&stake]["account_utxos"].as_array().unwrap().clone();
    let mut paths = Vec::new();
    for role in [Role::Receive, Role::Change] {
        for index in 0..20 {
            let addr = account.base_address(true, role, index).unwrap().to_bech32().unwrap();
            paths.push((addr, role as u32, index));
        }
    }
    rows.into_iter()
        .filter_map(|row| {
            let (_, role, index) = paths
                .iter()
                .find(|(a, _, _)| a == row["address"].as_str().unwrap())?;
            Some(PathedUtxo {
                utxo: serde_json::from_value(row).unwrap(),
                role: *role,
                index: *index,
            })
        })
        .collect()
}

/// Someone else's 25 receive addresses: the 15-word vector phrase's account.
fn their_addresses() -> Vec<String> {
    let doc = fixture("../../seedelf-crypto/tests/vectors/cardano_account.json");
    let phrase = doc["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["account"] == 0 && v["phrase"].as_str().unwrap().split(' ').count() == 15)
        .unwrap()["phrase"]
        .as_str()
        .unwrap()
        .to_string();
    let theirs = CardanoAccount::from_phrase(&phrase, 0).unwrap();
    (0..RECIPIENTS as u32)
        .map(|i| theirs.base_address(true, Role::Receive, i).unwrap().to_bech32().unwrap())
        .collect()
}

/// The private balance: four of the 12-word phrase's synthetic 25 ADA contract
/// UTxO (owned-utxos.json), 100 ADA under its own register.
fn private_balance() -> Vec<UtxoResponse> {
    let owned: Vec<UtxoResponse> = serde_json::from_value(
        fixture("../extension/tests/fixtures/owned-utxos.json")["owned_utxos"].clone(),
    )
    .unwrap();
    let base = owned.into_iter().next().unwrap();
    assert_eq!(base.value, "25000000");
    (0..4u64)
        .map(|i| UtxoResponse {
            tx_hash: format!("{:064x}", i + 1),
            ..base.clone()
        })
        .collect()
}

/// Someone else's Seedelf named `name`, under a fresh register of `key`: the
/// recorded preprod recipient's contract UTxO (transfer-preprod.json), renamed.
fn their_seedelf(name: &str, key: blstrs::Scalar) -> UtxoResponse {
    let register = Register::create(key).unwrap().rerandomize().unwrap();
    let mut utxo: UtxoResponse = serde_json::from_value(
        fixture("../extension/tests/fixtures/transfer-preprod.json")["recipient"].clone(),
    )
    .unwrap();
    utxo.asset_list.as_mut().unwrap()[0].asset_name = name.to_string();
    utxo.inline_datum = Some(InlineDatum {
        bytes: hex::encode(register.to_vec().unwrap()),
        value: json!({"constructor": 0, "fields": [
            {"bytes": register.generator}, {"bytes": register.public_value}]}),
    });
    utxo
}

fn register_from(datum: DatumOption) -> Register {
    let DatumOption::Data(data) = datum else {
        panic!("an inline datum")
    };
    let PlutusData::Constr(Constr { fields, .. }) = &data.0 else {
        panic!("a register is a constructor")
    };
    let fields = match fields {
        MaybeIndefArray::Def(v) | MaybeIndefArray::Indef(v) => v,
    };
    let bytes = |d: &PlutusData| match d {
        PlutusData::BoundedBytes(b) => hex::encode(b.as_slice()),
        _ => panic!("a point is bytes"),
    };
    Register::new(bytes(&fields[0]), bytes(&fields[1]))
}

/// What each output to `address` pays it.
fn paid_to(tx: &MultiEraTx, address: &str) -> Vec<u64> {
    tx.outputs()
        .iter()
        .filter(|o| o.address().unwrap().to_bech32().unwrap() == address)
        .map(|o| o.value().coin())
        .collect()
}

#[test]
fn public_send_pays_25_addresses_in_one_transaction() {
    let account = CardanoAccount::from_phrase(PHRASE, 0).unwrap();
    let to = their_addresses();
    let request = SendRequest {
        network: "preprod".into(),
        params: params(),
        utxos: account_utxos(&account),
        payments: to
            .iter()
            .map(|a| SendPayment {
                to: a.clone(),
                recipient: None,
                lovelace: Some(EACH.to_string()),
                tokens: vec![],
            })
            .collect(),
        withdrawal: None,
        note: None,
        invalid_hereafter: None,
    };
    let result = api::account_send(&account, request)
        .unwrap_or_else(|e| panic!("Send, {RECIPIENTS} addresses at 2 ADA from the public account: {e}"));
    assert_eq!(result.payments.len(), RECIPIENTS);
    let bytes = hex::decode(&result.tx_cbor).unwrap();
    let tx = MultiEraTx::decode(&bytes).unwrap();
    for a in &to {
        assert_eq!(paid_to(&tx, a), vec![EACH], "{a}");
    }
    let size = bytes.len() as u64;
    println!(
        "public Send: {RECIPIENTS} recipients, {} outputs, {size} bytes signed (limit {MAX_TX_SIZE}), fee {}",
        tx.outputs().len(),
        result.fee
    );
    assert!(size <= MAX_TX_SIZE, "{size}");
}

#[test]
fn private_send_pays_25_seedelfs_in_one_transaction() {
    let sk = seedelf_key_v1(PHRASE, 0).unwrap();
    let keys: Vec<blstrs::Scalar> = (0..RECIPIENTS).map(|_| random_scalar()).collect();
    let payments = keys
        .iter()
        .enumerate()
        .map(|(i, key)| {
            let name = format!("5eed0e1f{:056x}", i + 1);
            SeedelfPayment {
                recipient: their_seedelf(&name, *key),
                to: name,
                lovelace: Some(EACH.to_string()),
                tokens: vec![],
            }
        })
        .collect();
    let request = TransferRequest {
        network: "preprod".into(),
        params: params(),
        utxos: private_balance(),
        payments,
        classes: Default::default(),
        carry: false,
        seed: None,
        evaluation: None,
    };
    let parts = api::build_transfer_parts(sk, request)
        .unwrap_or_else(|e| panic!("Send, {RECIPIENTS} Seedelfs at 2 ADA from the private balance: {e}"));
    assert_eq!(parts.len(), 1, "several recipients go as one transaction");
    let part = &parts[0];
    assert_eq!(part.payments.len(), RECIPIENTS);
    assert!(part.payments.iter().all(|p| !p.to_self && p.lovelace == EACH.to_string()));
    let bytes = hex::decode(&part.tx_cbor).unwrap();
    let tx = MultiEraTx::decode(&bytes).unwrap();
    let outs: Vec<(Register, u64)> = tx
        .outputs()
        .iter()
        .map(|o| (register_from(o.datum().unwrap().into()), o.value().coin()))
        .collect();
    // Each Seedelf once, under a fresh copy of its own register.
    for key in &keys {
        let paid: Vec<u64> = outs
            .iter()
            .filter(|(r, _)| r.is_owned(*key).unwrap())
            .map(|(_, l)| *l)
            .collect();
        assert_eq!(paid, vec![EACH]);
    }
    let size = bytes.len() as u64 + TWO_WITNESSES;
    println!(
        "private Send: {RECIPIENTS} recipients, {} inputs, {} outputs, {size} bytes signed (limit {MAX_TX_SIZE}), fee {} (compute {})",
        part.inputs.len(),
        tx.outputs().len(),
        part.fee.total,
        part.fee.compute
    );
    assert!(size <= MAX_TX_SIZE, "{size}");
}

