// Chunk 51, gap-g9#2 (the trace verifier's test). Lovejoin's way-back rules read only this browser profile's own
// storage: the quiet after the wallet's own send (wallet.ts `sends`: `seedelf.sends` and spent.ts's SESSION_SPENT, both
// chrome.storage.session), one box a run and the spread after it (lovejoin.ts withdrawDueNow, over this profile's
// sealed `lovejoin.<network>` due times), and the holds while a withdraw may be on its way (`withdrawing`) or a chain is
// sent (`chains`, sessions.ts's `mixingAgain`). privacy.md:349-350 offers the phrase in a second Chrome profile, and
// :456 says a box a mix made comes back there "as any box does": the second profile finds the first's boxes
// (moreThanDue, found, scheduleFound) and brings them back on its own schedule. privacy.md *Timing* promises the way
// back keeps "from lining up with anything else the wallet does" (:440), never goes "within 5 minutes of the wallet's
// own send" (:442), and goes "one at a time: the others each wait a fresh 5 to 60 minutes" (:443); lovejoin.ts:6797
// says "two a minute apart say they're one owner's".
//
// The behaviour those promises ask for, asserted here: once a box of the phrase's has left the pool by a withdraw this
// profile didn't send (the other profile's, 40 s before, landed), this profile's next withdraw keeps
// QUIET_AFTER_SEND_MS from it. Only the phrase's key can withdraw its box, and someone else's mix leaves the phrase a
// box in its place, so a box of the wallet's gone from the pool with no withdraw of this profile's is the phrase's own
// withdraw sent elsewhere. Fails today: profile B's alarm run 40 s after profile A's withdraw takes the next box.
//
// This is the finder's code fix. Under its doc fix alone (privacy.md saying the rules hold per profile), this test goes.
//
// Two profiles: two wallets of one phrase over storage of their own (testBalances), one chain between them (a
// withdraw that lands is spent at both fakes of Koios), and one clock. The real WebAssembly builds each withdraw in
// v2's 5 ₳ pool; giveme.my's witness is stood in for, as lovejoin-restore.test.ts's `witnessed` does.
import { afterEach, describe, expect, it, vi } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import { LovejoinService, QUIET_AFTER_SEND_MS } from "../src/background/lovejoin";
import { AGREES, HOUR, PASSWORD, account } from "./chain-fixtures";
import { txIdOf } from "./fixtures/cbor";
import { busyFor, loadTestWasm, testBalances } from "./fakes";
import { ADA, ADA_POOL, ADA_ROWS, adaBox, madeByAdaMix, ownDatum } from "./v2-pools";

/** Three withdraws' worth of real WebAssembly, and a few hours of runs. */
const SLOW = { timeout: 120_000 };
const PHRASE = account(12).phrase;
/** The phrase's three boxes in v2's 5 ₳ pool, made five hours ago by someone else's mixes. */
const BOXES = ["b1", "b2", "b3"].map((h) => h.repeat(32));
const ref = (tx: string) => `${tx}#0`;

afterEach(() => void vi.restoreAllMocks());

/** One Chrome profile with the phrase restored and unlocked: its own storage, its own fake Koios and giveme.my. */
async function profile() {
  const t = testBalances({ pools: [ADA_POOL] });
  await t.wallet.create(PHRASE, PASSWORD);
  t.koios.evaluation = AGREES;
  t.koios.addedToAccounts.push(...ADA_ROWS);
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const wasm = loadTestWasm();
  const lovejoin = new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [ADA_POOL],
    // Every draw at its range's middle: Settings' 1 to 6 hours gives 3.5, a spread 32.5 minutes.
    random: () => 0.5,
  });
  return { t, lovejoin };
}

/** Pool `ADA`'s due times, as profile `t`'s sealed schedule keeps them. */
const adaDue = async (t: Awaited<ReturnType<typeof profile>>["t"]) =>
  (await t.store.get<{ pools?: Record<string, { due: number[] }> }>("lovejoin.preprod"))?.pools?.[ADA]?.due ?? [];

describe("r51 gap-g9#2: the phrase unlocked in two Chrome profiles", SLOW, () => {
  it("keeps a box's way back 5 minutes from the phrase's withdraw that the other profile sent a minute before", async () => {
    const a = await profile();
    const b = await profile();
    // What's stamped by the device's clock: both profiles' clocks are kept as one.
    vi.spyOn(Date, "now").mockImplementation(() => a.t.clock.now);
    const both = async (ms: number) => {
      await busyFor(a.t, ms);
      await busyFor(b.t, ms);
      expect(b.t.clock.now).toBe(a.t.clock.now);
    };
    // One chain: the same three boxes of the phrase's in the pool, read by both profiles, a mix having made each.
    const rows = await Promise.all(BOXES.map(async (tx) => adaBox(tx, await ownDatum(a.t.wallet), a.t.clock.now)));
    for (const p of [a, b]) {
      p.t.koios.addedToAccounts.push(...rows);
      madeByAdaMix(p.t.koios, ...BOXES);
    }
    const start = a.t.clock.now;
    // Profile B opens its Lovejoin page ten minutes in, and draws a due time for each box it finds: 3.5 hours on.
    const found = start + 10 * 60_000;
    const bDue = found + 3.5 * HOUR;
    // Profile A's own due times for its boxes, as its chain drew them: its first comes 40 s before B's.
    const aDue = bDue - 40_000;
    await a.t.store.set("lovejoin.preprod", { due: [], pools: { [ADA]: { due: [aDue, aDue + 2 * HOUR, aDue + 4 * HOUR] } }, chains: [] });

    // Each profile's unlock: its run sends nothing (privacy review §3.1).
    expect(await a.lovejoin.withdrawDue("preprod", true)).toEqual([]);
    expect(await b.lovejoin.withdrawDue("preprod", true)).toEqual([]);
    // Profile B's page finds the three boxes no record of its own accounts for, asks what made them (a mix), and gives
    // each a due time of B's own: B will bring A's boxes back by itself.
    await both(found - a.t.clock.now);
    await b.lovejoin.status("preprod");
    expect(await adaDue(b.t)).toEqual([bDue, bDue, bDue]);
    // The alarm's next runs: nothing is due yet on either.
    await both(60_000);
    expect(await a.lovejoin.withdrawDue("preprod")).toEqual([]);
    expect(await b.lovejoin.withdrawDue("preprod")).toEqual([]);

    // Profile A's first box comes due: its alarm brings it back, every rule of A's met.
    await both(aDue - a.t.clock.now);
    expect(await a.lovejoin.withdrawDue("preprod")).toHaveLength(1);
    const aAt = a.t.clock.now;
    expect(txInputs(a.t.koios.submitted.at(-1)!)).toContain(ref(BOXES[0]!));
    // It lands: the box is gone from the pool, for both profiles' reads.
    for (const p of [a, b]) p.t.koios.spent.add(ref(BOXES[0]!));

    // Profile B's alarm, each minute from 40 s later, while both stay unlocked.
    await both(40_000);
    let bAt: number | undefined;
    for (let run = 0; run < 120 && bAt === undefined; run++) {
      if ((await b.lovejoin.withdrawDue("preprod")).length) bAt = b.t.clock.now;
      else await both(60_000);
    }
    if (bAt !== undefined) {
      // B's withdraw spends another of the phrase's boxes, never the one A's took.
      const spent = txInputs(b.t.koios.submitted.at(-1)!);
      expect(spent.some((o) => o === ref(BOXES[1]!) || o === ref(BOXES[2]!))).toBe(true);
      expect(spent).not.toContain(ref(BOXES[0]!));
    }
    // Two of the phrase's boxes come back into Seedelf from one IP address: never within the quiet after the wallet's
    // own send, nor in a burst, whichever profile sent the first.
    const apart = bAt === undefined ? Infinity : bAt - aAt;
    expect(apart, `profile B's withdraw went ${apart / 1000} s after profile A's`).toBeGreaterThanOrEqual(QUIET_AFTER_SEND_MS);
  });
});

// Chunk 51, gap-g10#1: blanks the browser keeps must never push a name's last letters out of a one-line list.
// `white-space: nowrap` collapses only U+0020, tabs and line breaks, so an EM SPACE (U+2003), an IDEOGRAPHIC SPACE
// (U+3000) or a NO-BREAK SPACE (U+00A0) keeps its width. nameSkeleton drops them (NFKD makes each a U+0020), so a
// stranger's token named "SNEK" + 9 EM SPACEs + "x" (32 bytes, the asset-name limit) has the skeleton "snekx", isn't
// kept apart as passing for SNEK, and goes by its own name: Home's row, the Tokens page, the Add tokens picker and
// the swap's button cut it with an ellipsis to "SNEK        …" at the side panel's 360 px, the x gone. A DRep named
// "8Ball" + 40 EM SPACEs + "x" isn't counted with the two 8Balls, so its row has no "Shared name" tag, and the row
// shows "8Ball        …". The right behaviour, whichever fix: a name a list shows by its own words has its blanks
// as one, so its last letters fit; or it's kept apart (a token as a lookalike, by its fingerprint; a DRep flagged as
// sharing the name).
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";

import { drepName } from "../src/background/staking";
import type { TokenAmount } from "../src/shared/rpc";
import { plainName, sharedNames, sharing } from "../src/ui/format";
import { DrepRow } from "../src/ui/screens/Voting";
import { assetFingerprint, tokenText, viewToken } from "../src/ui/tokens";

const hex = (text: string) => Buffer.from(text, "utf8").toString("hex");
const STRANGER = "e675b46e4d2242c991a8932a99db3044e80515ae14b4c4ccf6b3f4c9";

const EM = " "; // EM SPACE: 1em wide, in Inter (styles.css's unicode-range takes U+2000-206F)
const IDEOGRAPHIC = "　"; // IDEOGRAPHIC SPACE
const NBSP = " "; // NO-BREAK SPACE

/** What `white-space: nowrap` draws of a label: runs of U+0020, tabs and line feeds as one space; other blanks stay. */
const asDrawn = (label: string) => label.replace(/[ \t\n]+/g, " ");
/** Two blanks or more in a row once drawn: JavaScript's \s holds every Unicode space separator. */
const BLANK_RUN = /\s{2,}/u;

/** A stranger's token, 1,000,000 of it, as the balances hold it. */
const held = (name: string): TokenAmount => {
  const ref = { policyId: STRANGER, assetName: hex(name) };
  return { ...ref, quantity: "1000000", decimals: 0, fingerprint: assetFingerprint(ref) };
};

describe("gap-g10#1: blanks the browser keeps never push a name's last letters out of a one-line list", () => {
  it("a stranger's token, padded after a listed token's name", () => {
    const cases: Array<["preprod" | "mainnet", string]> = [
      ["preprod", `tUSDM${EM.repeat(8)}x`],
      ["preprod", `MIN${IDEOGRAPHIC.repeat(9)}x`],
      ["preprod", `tUSDM${NBSP.repeat(13)}x`],
    ];
    // The finder's own case, on the mainnet list: a preprod-only build has none.
    if (__MAINNET_ENABLED__) cases.push(["mainnet", `SNEK${EM.repeat(9)}x`]);
    for (const [network, name] of cases) {
      // A name the ledger takes: at most 32 bytes.
      expect(Buffer.byteLength(name, "utf8"), name).toBeLessThanOrEqual(32);
      const token = held(name);
      const text = tokenText(network, token);
      // What Home's and the Tokens page's rows and the Add tokens picker show (viewToken), and the swap's button (tokenText).
      const label = viewToken(network, token).label;
      expect(label).toBe(text.label);
      // Kept apart, it goes by its fingerprint; by its own name, its blanks must draw as one.
      const shown = text.posesAs ? label : asDrawn(label);
      expect
        .soft(shown, `${JSON.stringify(name)} on ${network}: label ${JSON.stringify(label)}, posesAs ${text.posesAs}`)
        .not.toMatch(BLANK_RUN);
    }
  });

  it("a DRep, padded after a name two others share", () => {
    const EIGHT_A = "drep1y296z8tm7y7elwsmsewn4q2tdr5gu0fqztq97yttlpv7zycvsl554";
    const EIGHT_B = "drep1y296zyw2r8rcsy7slkd7l687hh88xc0m6ac2y3h2r3mvsdgc9q6yy";
    const IMPOSTOR = `drep1y2${"q".repeat(51)}`;
    const givenName = `8Ball${EM.repeat(40)}x`;
    // What the list keeps of its CIP-119 givenName: the worker's drepName, whose copy is dreps.mjs's nameOf.
    const stored = drepName(givenName);
    expect(stored).toBeDefined();
    const list = [
      { id: EIGHT_A, name: "8Ball" },
      { id: EIGHT_B, name: "8Ball" },
      { id: IMPOSTOR, name: stored! },
    ];
    // Counted, and each row flagged, as Voting and DrepSearch do.
    const counts = sharedNames(list, (d) => d.name);
    const row = (d: { id: string; name: string }) =>
      renderToStaticMarkup(
        createElement(DrepRow, { drep: d, shared: sharing(counts, d.name) > 1, disabled: false, onPick: () => undefined }),
      );
    for (const d of list.slice(0, 2)) expect(row(d)).toContain("Shared name");
    const html = row(list[2]!);
    const label = /<span class="token-row__label">([^<]*)<\/span>/.exec(html)?.[1];
    expect(label).toBe(plainName(stored!));
    const flagged = html.includes("Shared name");
    expect(flagged ? "" : asDrawn(label!), `the padded 8Ball's row, flagged ${flagged}, label ${JSON.stringify(label)}`).not.toMatch(
      BLANK_RUN,
    );
  });
});

// Chunk 51, gap-g10#2: public Activity names who paid the account by their address, cut in the middle by
// MiddleEllipsis (screens/Activity.tsx `Who`): its head gives way to the row's width, and only its last six
// characters never do. Those six are the bech32 checksum, and a stranger matches them for free: they keep their own
// payment key and choose six symbols of their address's stake part, which nothing signs for, by solving the
// checksum's linear equations. Their 1 ₳ then lists as "ad… e35a3x" beside the user's payment to "addr1qx2fxv2u…
// e35a3x". What a row keeps whatever its width must tell two payment keys apart.
//
// The cut is the stylesheet's: `.middle-ellipsis__head` gives way, `.middle-ellipsis__tail` never does, and
// `.activity__sub .middle-ellipsis` shrinks to 9ch beside an amount the sender chooses. So this reads what the markup
// leaves outside the part that gives way. The verifier's record has a headless-Chrome measure of the real rows.
import { createHash, createPrivateKey, createPublicKey } from "node:crypto";
import { readFileSync } from "node:fs";

import { blake2b } from "@noble/hashes/blake2.js";
import * as wasm from "@seedelf/wasm";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { beforeAll, describe, expect, it } from "vitest";

import { Who } from "../src/ui/screens/Activity";

/** CIP-19's mainnet base address (key payment, key stake): the address the user paid, Bob's. */
const BOB = "addr1qx2fxv2umyhttkxyxp8x0dlpdt3k6cwng5pxj3jhsydzer3n0d3vllmyqwsx5wktcd8cc3sq835lu7drv2xwl2wywfgse35a3x";

// BIP-173 bech32, as Cardano's addresses use it (no 90-character cap).
const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

function polymod(values: number[]): number {
  let chk = 1;
  for (const v of values) {
    const top = chk >>> 25;
    chk = (((chk & 0x1ffffff) << 5) ^ v) >>> 0;
    for (let i = 0; i < 5; i++) if ((top >>> i) & 1) chk = (chk ^ GEN[i]!) >>> 0;
  }
  return chk;
}

const expand = (hrp: string) => [...[...hrp].map((c) => c.charCodeAt(0) >> 5), 0, ...[...hrp].map((c) => c.charCodeAt(0) & 31)];

/** The six checksum symbols of `data` under `hrp`, as one 30-bit number. */
const checksum = (hrp: string, data: number[]) => (polymod([...expand(hrp), ...data, 0, 0, 0, 0, 0, 0]) ^ 1) >>> 0;

function encode(hrp: string, data: number[]): string {
  const sum = checksum(hrp, data);
  const tail = Array.from({ length: 6 }, (_, i) => (sum >>> (5 * (5 - i))) & 31);
  return `${hrp}1${[...data, ...tail].map((v) => CHARSET[v]).join("")}`;
}

/** Bytes as 5-bit symbols, the last padded with zeros. */
function words(bytes: Uint8Array): number[] {
  const out: number[] = [];
  let acc = 0;
  let bits = 0;
  for (const b of bytes) {
    acc = ((acc << 8) | b) & 0xfff;
    bits += 8;
    while (bits >= 5) {
      bits -= 5;
      out.push((acc >> bits) & 31);
    }
  }
  if (bits) out.push((acc << (5 - bits)) & 31);
  return out;
}

/** A mask of `columns` whose XOR is `target`, over GF(2), if there is one. */
function solve(columns: number[], target: number): number | undefined {
  const basis: Array<{ v: number; m: number } | undefined> = new Array(30);
  columns.forEach((column, j) => {
    let v = column;
    let m = 2 ** j;
    for (let bit = 29; bit >= 0 && v; bit--) {
      if (!((v >>> bit) & 1)) continue;
      const b = basis[bit];
      if (!b) {
        basis[bit] = { v, m };
        return;
      }
      v = (v ^ b.v) >>> 0;
      m = (m ^ b.m) >>> 0;
    }
  });
  let v = target;
  let m = 0;
  for (let bit = 29; bit >= 0 && v; bit--) {
    if (!((v >>> bit) & 1)) continue;
    const b = basis[bit];
    if (!b) return undefined;
    v = (v ^ b.v) >>> 0;
    m = (m ^ b.m) >>> 0;
  }
  return m;
}

/**
 * A mainnet base address under `payment`, the stranger's own key hash, ending in `target`'s last six characters: its
 * stake part starts as `target`'s, and six of its symbols are solved for. No grinding, no one else's key.
 */
function lookalike(target: string, payment: Uint8Array): string {
  const bytes = new Uint8Array(57);
  bytes[0] = 0x01; // a base address, key payment and key stake, on mainnet
  bytes.set(payment, 1);
  bytes.set(Buffer.from(wasm.cip30Address(target), "hex").subarray(29), 29);
  const data = words(bytes);
  const want = [...target.slice(-6)].reduce((n, c) => n * 32 + CHARSET.indexOf(c), 0);
  // Symbols 60 to 65 hold bits 300 to 329: inside the stake hash (bits 232 to 455).
  const free = [60, 61, 62, 63, 64, 65];
  const base = checksum("addr", data);
  const columns = free.flatMap((p) =>
    [0, 1, 2, 3, 4].map((bit) => {
      const flipped = [...data];
      flipped[p] = flipped[p]! ^ (1 << bit);
      return (checksum("addr", flipped) ^ base) >>> 0;
    }),
  );
  const mask = solve(columns, (base ^ want) >>> 0);
  if (mask === undefined) throw new Error("no solution for these six symbols");
  for (let j = 0; j < 30; j++) if ((mask >>> j) & 1) data[free[Math.floor(j / 5)]!] = data[free[Math.floor(j / 5)]!]! ^ (1 << (j % 5));
  return encode("addr", data);
}

/** The stranger's payment key hash: Blake2b-224 of an Ed25519 key of their own. */
function strangersKeyHash(): Uint8Array {
  const seed = createHash("sha256").update("r51 gap-g10#2: the stranger's own key").digest();
  const pkcs8 = Buffer.concat([Buffer.from("302e020100300506032b657004220420", "hex"), seed]);
  const vkey = createPublicKey(createPrivateKey({ key: pkcs8, format: "der", type: "pkcs8" }))
    .export({ format: "der", type: "spki" })
    .subarray(-32);
  return blake2b(vkey, { dkLen: 28 });
}

/** Who's markup for `name`, as Activity's list renders it. */
const shown = (name: string) => renderToStaticMarkup(createElement(Who, { name }));

/** What the row shows whatever its width: its text, but for the head MiddleEllipsis lets give way. */
const kept = (html: string) =>
  html
    .replace(/<span class="middle-ellipsis__head">[^<]*<\/span>/g, "")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&");

beforeAll(() => {
  wasm.initSync({ module: readFileSync(new URL("../../wasm/pkg/seedelf_wasm_bg.wasm", import.meta.url)) });
});

describe("public Activity's counterparty (chunk 51, gap-g10#2)", () => {
  it("keeps, at any width, a part of the address that a stranger's lookalike can't match for free", () => {
    const payment = strangersKeyHash();
    const poisoner = lookalike(BOB, payment);

    // The stranger's address is a valid mainnet key address the wallet pays (the wallet's own parser, pallas), under
    // their own payment key, not Bob's, and it ends in Bob's six characters.
    expect(() => wasm.checkPayableAddress(poisoner, wasm.Network.Mainnet)).not.toThrow();
    const theirs = wasm.cip30Address(poisoner);
    const bobs = wasm.cip30Address(BOB);
    expect(theirs.slice(0, 2)).toBe("01");
    expect(theirs.slice(2, 58)).toBe(Buffer.from(payment).toString("hex"));
    expect(theirs.slice(2, 58)).not.toBe(bobs.slice(2, 58));
    expect(poisoner).toHaveLength(BOB.length);
    expect(poisoner.slice(-6)).toBe(BOB.slice(-6));

    // What the row keeps when the head gives way. Today that's "e35a3x" for both: the stranger's 1 ₳ reads as Bob's.
    expect(kept(shown(poisoner))).not.toBe(kept(shown(BOB)));
    // A fixed run of the payment part, as Send's note keeps it (shortHex(address, 14, 8)): "addr1q" and 8 more.
    expect(kept(shown(BOB))).toContain(BOB.slice(0, 14));
  });
});

// Chunk 51, gap-g10#3: the Add tokens picker and the swap's pay picker show a lookalike token's warning as a plain
// grey sub line, cut to one line.
//
// A token whose own name passes for a listed one goes by its fingerprint, and its view's second line is a warning,
// "Calls itself tUSDM, not on the wallet's list", with `warn` set (tokens.ts viewToken). TokenView.warn's rule
// (tokens.ts, chunk 23's review, H-9): shown whole, never cut. Home's TokenRow (TokenList.tsx) gives that line
// `wrap token-row__sub--warn`: styles.css's `.token-row__sub.wrap` (white-space: normal) and `.token-row__sub--warn`
// (color: var(--warn)). The Add tokens picker (TokenAmounts.tsx's TokenPicker, opened from Send, Send privately, Make
// private, Make public, a site session's top-up and the connector's funding) renders the same view's line with
// `token-row__sub` alone, which is grey (var(--muted)) and one line, cut with an ellipsis (overflow: hidden,
// text-overflow: ellipsis, white-space: nowrap). The swap's token picker (Swaps.tsx's TokenSelect) does the same with
// an own pick's mark, "Not on the wallet's list: it calls itself tUSDM, but it isn't the listed tUSDM", which a
// review shows in the warning's colour (TokenAmountText's token-mark--warn).
//
// The right behaviour: both pickers carry a lookalike's warning as Home's list does. Home's row is the control: the
// token is a lookalike, its view says warn, and the list gives its line the two classes. The token is preprod's
// tUSDM under a stranger's policy, so the test doesn't hang on whether the mainnet list is built in.
import { createElement, type ReactElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";

import { TokenPicker } from "../src/ui/components/TokenAmounts";
import { TokenList } from "../src/ui/components/TokenList";
import { NetworkContext } from "../src/ui/network";
import { TokenSelect } from "../src/ui/screens/Swaps";
import { tokenText, viewToken } from "../src/ui/tokens";

const STRANGER = "e675b46e4d2242c991a8932a99db3044e80515ae14b4c4ccf6b3f4c9";
const hex = (text: string) => Buffer.from(text, "utf8").toString("hex");
/** A stranger's 1,000,000 "tUSDM", the scenario's amount (the class doesn't depend on it; the cut does). */
const lookalike = { policyId: STRANGER, assetName: hex("tUSDM"), quantity: "1000000", decimals: 0, fingerprint: "" };
const tokens = [lookalike];
const noop = () => undefined;
const seedelf = { lovelace: "50000000", utxos: 1, seedelfs: [], locked: { lovelace: "0", tokens: [], utxos: 0 }, tokens };

const html = (element: ReactElement) =>
  renderToStaticMarkup(createElement(NetworkContext.Provider, { value: "preprod" }, element));

/** The class of the span whose text starts with `start`, as React writes it (an apostrophe is &#x27;). */
function classOf(markup: string, start: string): string | undefined {
  const escaped = start.replace(/'/g, "&#x27;").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`<span class="([^"]*)">${escaped}[^<]*</span>`).exec(markup)?.[1];
}

const classes = (c: string | undefined) => (c ?? "").split(/\s+/).filter(Boolean);
const WARNED = ["token-row__sub", "wrap", "token-row__sub--warn"];

describe("gap-g10#3: a lookalike token's warning in the pickers", () => {
  const text = tokenText("preprod", lookalike);
  const view = viewToken("preprod", lookalike);
  const warning = "Calls itself tUSDM, not on the wallet's list";

  it("the control: Home's list gives the lookalike's warning its wrap and warn classes", () => {
    expect(text.posesAs, "the stranger's tUSDM passes for the listed one").toBe("tUSDM");
    expect(view.label, "it goes by its fingerprint").toBe(text.id);
    expect(view.sub).toBe(warning);
    expect(view.warn).toBe(true);
    const home = classOf(html(createElement(TokenList, { tokens, of: "seedelf", testId: "tokens", onViewAll: noop })), warning);
    expect(home, "Home's row carries the warning line").toBeDefined();
    expect(classes(home)).toEqual(expect.arrayContaining(WARNED));
  });

  it("the Add tokens picker gives it the same classes, so it shows whole, in the warning's colour", () => {
    const markup = html(createElement(TokenPicker, { tokens, onClose: noop, onPick: noop }));
    expect(markup, "the picker lists the token by its fingerprint").toContain(`aria-label="${text.id}"`);
    const picker = classOf(markup, warning);
    expect(picker, "the picker's row carries the warning line").toBeDefined();
    expect(classes(picker), "the picker's warning line").toEqual(expect.arrayContaining(WARNED));
  });

  it("the swap's pay picker gives its mark the same classes", () => {
    const markup = html(createElement(TokenSelect, { which: "pay", seedelf, onPick: noop, onClose: noop }));
    const swap = classOf(markup, "Not on the wallet's list: it calls itself tUSDM, but it isn't the listed tUSDM");
    expect(swap, "the swap's row carries the mark").toBeDefined();
    expect(classes(swap), "the swap's mark line").toEqual(expect.arrayContaining(WARNED));
  });
});
